    private fun icon(name: String, pathData: String): ImageVector =
        ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 256f, viewportHeight = 256f)
            .addPath(pathData = PathParser().parsePathString(pathData).toNodes(), fill = SolidColor(androidx.compose.ui.graphics.Color.Black))
            .build()
